command(@"
extends Node2D

@export var damage: int = 30
@export var attack_interval: float = 1.5
@export var thickness: float = 10.0

@export var projectile_scene: PackedScene = preload("res://scenes/weapons/laser_projectile.tscn")

var attack_timer: Timer

func _ready() -> void:
	attack_timer = Timer.new()
	attack_timer.wait_time = attack_interval
	attack_timer.autostart = true
	attack_timer.timeout.connect(_on_attack_timer_timeout)
	add_child(attack_timer)

func _on_attack_timer_timeout() -> void:
	var targets = get_tree().get_nodes_in_group("enemy")
	targets.append_array(get_tree().get_nodes_in_group("destructible"))
	if targets.is_empty():
		return

	var nearest_target: Node2D = null
	var min_dist: float = INF
	for target in targets:
		if is_instance_valid(target):
			var dist := global_position.distance_squared_to(target.global_position)
			if dist < min_dist:
				min_dist = dist
				nearest_target = target

	if nearest_target and projectile_scene:
		var dir := (nearest_target.global_position - global_position).normalized()
		var proj = projectile_scene.instantiate()
		proj.global_position = global_position
		proj.damage = damage
		proj.thickness = thickness
		proj.set_direction(dir)
		get_tree().current_scene.add_child(proj)
"@ | Out-File -FilePath scripts/weapons/laser_weapon.gd -Encoding UTF8)

command(@"
extends Area2D

@export var damage: int = 30
@export var thickness: float = 10.0
@export var length: float = 800.0
@export var lifetime: float = 0.3

var direction: Vector2 = Vector2.RIGHT

@onready var collision_shape: CollisionShape2D = \$CollisionShape2D
@onready var color_rect: ColorRect = \$ColorRect

func _ready() -> void:
	# レーザーの形状設定
	var rect_shape = RectangleShape2D.new()
	rect_shape.size = Vector2(length, thickness)
	collision_shape.shape = rect_shape
	collision_shape.position = Vector2(length / 2, 0)

	color_rect.size = Vector2(length, thickness)
	color_rect.position = Vector2(0, -thickness / 2)
	color_rect.color = Color(0.2, 0.8, 1.0, 1.0)

	body_entered.connect(_on_body_entered)

	# フェードアウト
	var tween = create_tween()
	tween.tween_property(color_rect, "color:a", 0.0, lifetime)
	tween.tween_callback(queue_free)

func set_direction(dir: Vector2) -> void:
	direction = dir.normalized()
	rotation = direction.angle()

func _on_body_entered(body: Node2D) -> void:
	if body.has_method("take_damage") and not body.is_in_group("player"):
		body.take_damage(damage, direction)
"@ | Out-File -FilePath scripts/weapons/laser_projectile.gd -Encoding UTF8)

command(New-Item -Path 'c:\Users\remak\source\repos\AsaSurvivor\scripts\components\weapon_manager.gd' -ItemType File -Value 'extends Node
class_name WeaponManager

var weapon_levels: Dictionary = {}
var global_damage_multiplier: float = 1.0
var global_cooldown_multiplier: float = 1.0
@export var max_weapons: int = 3

func get_weapon_level(weapon_id: String) -> int:
	return weapon_levels.get(weapon_id, 0)

func has_weapon(weapon_id: String) -> bool:
	return weapon_levels.has(weapon_id)

func add_weapon(weapon_id: String, weapon_node: Node) -> void:
	if not weapon_levels.has(weapon_id):
		weapon_levels[weapon_id] = 1
	add_child(weapon_node)
	_apply_weapon_stats(weapon_id)

func upgrade_weapon(weapon_id: String) -> void:
	if weapon_levels.has(weapon_id):
		weapon_levels[weapon_id] = min(weapon_levels[weapon_id] + 1, 3)
		_apply_weapon_stats(weapon_id)

func refresh_all_weapons() -> void:
	for weapon_id in weapon_levels.keys():
		_apply_weapon_stats(weapon_id)

func set_evolution_weapon(base_id: String, weapon_node: Node) -> void:
	for child in get_children():
		if child.name.to_lower().begins_with(base_id):
			child.queue_free()
	weapon_levels[base_id] = 4
	add_child(weapon_node)

func _apply_weapon_stats(weapon_id: String) -> void:
	var w_level = weapon_levels[weapon_id]
	for child in get_children():
		if child.name.to_lower().begins_with(weapon_id):
			if weapon_id == "orbit":
				child.damage = int(20 * w_level * global_damage_multiplier)
				child.rotation_speed = 2.5 + (w_level * 0.5)
			elif weapon_id == "melee":
				child.damage = int(40 * w_level * global_damage_multiplier)
				child.attack_interval = max(0.4, (1.2 - (w_level * 0.3)) * global_cooldown_multiplier)
			elif weapon_id == "meteor":
				child.damage = int(60 * w_level * global_damage_multiplier)
				child.drop_count = 3 + w_level
				if "attack_interval" in child:
					child.attack_interval = max(0.5, 3.0 * global_cooldown_multiplier)
			elif weapon_id == "laser":
				child.damage = int(30 * w_level * global_damage_multiplier)
				child.thickness = 10.0 + (w_level * 5.0)
				if "attack_interval" in child:
					child.attack_interval = max(0.2, 1.5 * global_cooldown_multiplier)
')

command(New-Item -Path 'c:\Users\remak\source\repos\AsaSurvivor\scripts\components\relic_manager.gd' -ItemType File -Value 'extends Node
class_name RelicManager

var active_relics: Array[String] = []
var has_explosion_relic: bool = false
var has_shield: bool = false
var shield_active: bool = false

var regen_timer: Timer = null
var shield_timer: Timer = null

@onready var health_component = $"../HealthComponent"

func add_relic(relic_id: String) -> void:
	if not active_relics.has(relic_id):
		active_relics.append(relic_id)

	match relic_id:
		"magnet":
			var parent = get_parent()
			if parent.has_node("MagnetArea/CollisionShape2D"):
				var shape = parent.get_node("MagnetArea/CollisionShape2D").shape
				if shape is CircleShape2D:
					shape.radius *= 2.5
		"regen":
			if not regen_timer:
				regen_timer = Timer.new()
				regen_timer.wait_time = 5.0
				regen_timer.autostart = true
				regen_timer.timeout.connect(_on_regen_timeout)
				add_child(regen_timer)
		"explosion":
			has_explosion_relic = true
		"shield":
			if not has_shield:
				has_shield = true
				shield_active = true
				shield_timer = Timer.new()
				shield_timer.wait_time = 15.0
				shield_timer.one_shot = true
				shield_timer.timeout.connect(_on_shield_timeout)
				add_child(shield_timer)

	SignalBus.relic_acquired.emit(relic_id)

func _on_regen_timeout() -> void:
	if health_component:
		health_component.heal(5)

func _on_shield_timeout() -> void:
	shield_active = true
	var p = get_parent()
	if p.has_method("queue_redraw"):
		p.queue_redraw()

func consume_shield() -> bool:
	if has_shield and shield_active:
		shield_active = false
		shield_timer.start()
		var p = get_parent()
		if p.has_method("queue_redraw"):
			p.queue_redraw()
		return true
	return false
')

command(New-Item -Path 'c:\Users\remak\source\repos\AsaSurvivor\scripts\player.gd' -ItemType File -Value 'extends CharacterBody2D
class_name Player

@export var speed: float = 260.0

@onready var sprite: Sprite2D = $Sprite2D
@onready var input_comp: InputComponent = $InputComponent
@onready var health_comp: HealthComponent = $HealthComponent
@onready var exp_comp: ExperienceComponent = $ExperienceComponent
@onready var weapon_mgr: WeaponManager = $WeaponManager
@onready var relic_mgr: RelicManager = $RelicManager
@onready var magnet_area: Area2D = $MagnetArea

func _ready() -> void:
	add_to_group("player")

	var weapon_id: String = ""

	if Global.selected_character == "warrior":
		sprite.modulate = Color(1.0, 0.4, 0.4)
		health_comp.set_max_health(150)
		speed = 220.0
		weapon_id = "melee"
	elif Global.selected_character == "thief":
		sprite.modulate = Color(0.4, 1.0, 0.4)
		health_comp.set_max_health(80)
		speed = 340.0
		weapon_id = "orbit"
	elif Global.selected_character == "mage":
		sprite.modulate = Color(0.4, 0.4, 1.0)
		health_comp.set_max_health(100)
		speed = 260.0
		weapon_id = "laser"

	var weapon_scene_path = "res://scenes/weapons/" + weapon_id + "_weapon.tscn"
	if ResourceLoader.exists(weapon_scene_path):
		var weapon_scene = load(weapon_scene_path)
		weapon_mgr.add_weapon(weapon_id, weapon_scene.instantiate())

	magnet_area.area_entered.connect(_on_magnet_area_entered)
	health_comp.died.connect(_on_died)

func _physics_process(_delta: float) -> void:
	if health_comp.current_health <= 0:
		return

	velocity = input_comp.input_vector * speed
	move_and_slide()

	if velocity.x < 0:
		sprite.flip_h = true
	elif velocity.x > 0:
		sprite.flip_h = false

func take_damage(amount: int) -> void:
	var has_shield = false
	if relic_mgr.has_shield and relic_mgr.shield_active:
		has_shield = relic_mgr.consume_shield()
		if has_shield:
			_start_invulnerability_visuals()
			return

	var prevented = health_comp.take_damage(amount, has_shield)
	if not prevented and health_comp.current_health > 0:
		_start_invulnerability_visuals()

func _start_invulnerability_visuals() -> void:
	health_comp.is_invulnerable = true
	set_collision_mask_value(2, false)
	set_collision_layer_value(1, false)

	var tween := create_tween().set_loops(3)
	tween.tween_property(sprite, "modulate:a", 0.3, health_comp.invulnerability_duration / 6.0)
	tween.tween_property(sprite, "modulate:a", 1.0, health_comp.invulnerability_duration / 6.0)

	await get_tree().create_timer(health_comp.invulnerability_duration).timeout

	health_comp.is_invulnerable = false
	set_collision_mask_value(2, true)
	set_collision_layer_value(1, true)
	sprite.modulate.a = 1.0

func _on_died() -> void:
	set_physics_process(false)
	visible = false

func _on_magnet_area_entered(area: Area2D) -> void:
	if area.has_method("attract_to"):
		area.attract_to(self)

func _draw() -> void:
	if relic_mgr and relic_mgr.shield_active:
		draw_circle(Vector2.ZERO, 35.0, Color(1.0, 1.0, 0.2, 0.4))
		draw_arc(Vector2.ZERO, 35.0, 0, TAU, 32, Color(1.0, 1.0, 0.2, 0.8), 2.0)

var current_health: int:
	get: return health_comp.current_health if health_comp else 0
var max_health: int:
	get: return health_comp.max_health if health_comp else 100
var current_exp: int:
	get: return exp_comp.current_exp if exp_comp else 0
var exp_to_next_level: int:
	get: return exp_comp.exp_to_next_level if exp_comp else 30
var level: int:
	get: return exp_comp.level if exp_comp else 1
var weapon_levels: Dictionary:
	get: return weapon_mgr.weapon_levels if weapon_mgr else {}
var max_weapons: int:
	get: return weapon_mgr.max_weapons if weapon_mgr else 3

func add_exp(amount: int) -> void:
	if exp_comp:
		exp_comp.add_exp(amount)

func add_relic(relic_id: String) -> void:
	if relic_mgr:
		relic_mgr.add_relic(relic_id)

func add_weapon(weapon_id: String, weapon_node: Node) -> void:
	if weapon_mgr:
		weapon_mgr.add_weapon(weapon_id, weapon_node)

func get_weapon_level(weapon_id: String) -> int:
	return weapon_mgr.get_weapon_level(weapon_id) if weapon_mgr else 0

func apply_upgrade(upgrade_id: String) -> void:
	if upgrade_id.begins_with("upgrade_") or upgrade_id.begins_with("new_weapon_"):
		var weapon_id = upgrade_id.replace("upgrade_", "").replace("new_weapon_", "")
		if weapon_mgr.has_weapon(weapon_id):
			weapon_mgr.upgrade_weapon(weapon_id)
		else:
			var weapon_scene_path = "res://scenes/weapons/" + weapon_id + "_weapon.tscn"
			if ResourceLoader.exists(weapon_scene_path):
				var weapon_scene = load(weapon_scene_path)
				weapon_mgr.add_weapon(weapon_id, weapon_scene.instantiate())
	else:
		match upgrade_id:
			"damage":
				weapon_mgr.global_damage_multiplier += 0.1
				weapon_mgr.refresh_all_weapons()
			"attack_speed":
				weapon_mgr.global_cooldown_multiplier = max(0.2, weapon_mgr.global_cooldown_multiplier - 0.1)
				weapon_mgr.refresh_all_weapons()
			"magnet_range":
				var shape = magnet_area.get_node("CollisionShape2D").shape
				if shape is CircleShape2D:
					shape.radius *= 1.3
			"armor":
				health_comp.armor += 2
			"move_speed":
				speed += 35.0
			"max_health":
				health_comp.increase_max_health(25, 40)

	exp_comp.consume_pending_level_up()
' -Force)

command(New-Item -Path 'c:\Users\remak\source\repos\AsaSurvivor\scripts\systems\enemy_spawner.gd' -ItemType File -Value 'extends Node
class_name EnemySpawner

@export var enemy_scene: PackedScene = preload("res://scenes/enemy.tscn")
@export var enemy_fast_scene: PackedScene = preload("res://scenes/enemy_fast.tscn")
@export var enemy_tank_scene: PackedScene = preload("res://scenes/enemy_tank.tscn")
@export var enemy_boss_scene: PackedScene = preload("res://scenes/enemy_boss.tscn")
@export var spawn_radius: float = 700.0
@export var player_node_path: NodePath
const MAX_ENEMIES: int = 150

var survival_time: float = 0.0
var spawn_interval: float = 1.5
var next_boss_time: float = 90.0
var is_boss_fight: bool = false
var is_active: bool = true

@onready var player = get_node_or_null(player_node_path)
@onready var spawn_timer: Timer = Timer.new()

func _ready() -> void:
	spawn_timer.wait_time = spawn_interval
	spawn_timer.timeout.connect(_on_spawn_timer_timeout)
	add_child(spawn_timer)
	spawn_timer.start()

func _process(delta: float) -> void:
	if not is_active:
		return

	if not is_boss_fight:
		survival_time += delta
		spawn_interval = max(0.3, 1.5 - (survival_time / 60.0) * 0.4)
		spawn_timer.wait_time = spawn_interval

	if survival_time >= next_boss_time and not is_boss_fight:
		spawn_boss()
		next_boss_time += 90.0

func _on_spawn_timer_timeout() -> void:
	if not is_active or is_boss_fight or not is_instance_valid(player):
		return

	var current_enemies = get_tree().get_nodes_in_group("enemy").size()
	if current_enemies >= MAX_ENEMIES:
		return

	var spawn_count: int = 1 + int(survival_time / 30.0)
	spawn_count = min(spawn_count, MAX_ENEMIES - current_enemies)

	for i in range(spawn_count):
		spawn_enemy()

func spawn_enemy() -> void:
	if not is_instance_valid(player):
		return

	var scene_to_spawn := enemy_scene
	var rand_val := randf()

	if survival_time > 60.0:
		if rand_val < 0.2:
			scene_to_spawn = enemy_tank_scene
		elif rand_val < 0.5:
			scene_to_spawn = enemy_fast_scene
	elif survival_time > 30.0:
		if rand_val < 0.3:
			scene_to_spawn = enemy_fast_scene

	var random_angle := randf() * TAU
	var spawn_offset := Vector2(cos(random_angle), sin(random_angle)) * spawn_radius
	var spawn_pos := player.global_position + spawn_offset

	var enemy = scene_to_spawn.instantiate()
	enemy.global_position = spawn_pos

	if scene_to_spawn == enemy_fast_scene:
		enemy.score_value = 15
	elif scene_to_spawn == enemy_tank_scene:
		enemy.score_value = 30
	else:
		enemy.score_value = 10

	var time_factor := 1.0 + (survival_time / 60.0) * 0.5
	enemy.max_health = int(enemy.max_health * time_factor)
	enemy.speed = min(enemy.speed * 1.5, enemy.speed + (survival_time / 60.0) * 10.0)

	enemy.died.connect(_on_enemy_died)
	add_child(enemy)

func spawn_boss() -> void:
	if not enemy_boss_scene or not is_instance_valid(player):
		return

	is_boss_fight = true
	SignalBus.boss_spawned.emit()

	var enemies = get_tree().get_nodes_in_group("enemy")
	for enemy in enemies:
		enemy.queue_free()

	var random_angle := randf() * TAU
	var spawn_offset := Vector2(cos(random_angle), sin(random_angle)) * spawn_radius
	var spawn_pos := player.global_position + spawn_offset

	var boss = enemy_boss_scene.instantiate()
	boss.global_position = spawn_pos

	if survival_time >= 180.0:
		boss.set_meta("is_final_boss", true)
		boss.get_node("Sprite2D").modulate = Color(1.0, 0.1, 0.1)
		boss.get_node("Sprite2D").scale = Vector2(2.5, 2.5)
		boss.max_health = 15000
		boss.speed = 120.0
		boss.score_value = 10000
	else:
		boss.max_health = 1500 + int(survival_time / 90.0) * 1000
		boss.speed = 80.0 + (survival_time / 90.0) * 10.0
		boss.score_value = 1000

	boss.died.connect(_on_boss_died)
	add_child(boss)

func _on_boss_died(boss: CharacterBody2D) -> void:
	SignalBus.enemy_died.emit(boss)
	is_boss_fight = false

	if boss.has_meta("is_final_boss"):
		SignalBus.game_cleared.emit()

func _on_enemy_died(enemy: CharacterBody2D) -> void:
	SignalBus.enemy_died.emit(enemy)
')

