command(New-Item -Path 'c:\Users\remak\source\repos\AsaSurvivor\scripts\main.gd' -ItemType File -Value 'extends Node2D

var kill_count: int = 0
var score: int = 0
var is_game_over: bool = false
var is_game_clear: bool = false

@onready var player = $Player
@onready var hud = $HUD
@onready var enemy_spawner = $EnemySpawner
@onready var item_spawner = $ItemSpawner

func _ready() -> void:
	SignalBus.enemy_died.connect(_on_enemy_died)
	SignalBus.player_died.connect(_on_player_died)
	SignalBus.game_cleared.connect(_on_game_cleared)
	SignalBus.score_gained.connect(_on_score_gained)

func _on_enemy_died(enemy: Node2D) -> void:
	kill_count += 1
	var gained_score = enemy.score_value if "score_value" in enemy else 10
	score += gained_score

	if hud and hud.has_method("update_kills"):
		hud.update_kills(kill_count)
	if hud and hud.has_method("update_score"):
		hud.update_score(score)

func _on_player_died() -> void:
	is_game_over = true
	if enemy_spawner:
		enemy_spawner.is_active = false
	if item_spawner:
		item_spawner.is_active = false

	if hud and hud.has_method("show_game_over"):
		var survival_time = enemy_spawner.survival_time if enemy_spawner else 0.0
		hud.show_game_over(survival_time, kill_count)

func _on_score_gained(amount: int) -> void:
	score += amount
	if hud and hud.has_method("update_score"):
		hud.update_score(score)

func _on_game_cleared() -> void:
	is_game_clear = true
	is_game_over = true
	if enemy_spawner:
		enemy_spawner.is_active = false
	if item_spawner:
		item_spawner.is_active = false

	if hud and hud.has_method("show_game_clear"):
		var survival_time = enemy_spawner.survival_time if enemy_spawner else 0.0
		hud.show_game_clear(survival_time, kill_count, score)
' -Force)

command(New-Item -Path 'c:\Users\remak\source\repos\AsaSurvivor\scripts\ui\player_stats_ui.gd' -ItemType File -Value 'extends Control
class_name PlayerStatsUI

@onready var hp_bar: ProgressBar = $HPContainer/HPBar
@onready var hp_label: Label = $HPContainer/HPLabel
@onready var exp_bar: ProgressBar = $EXPContainer/EXPBar
@onready var level_label: Label = $EXPContainer/LevelLabel
@onready var relic_container: HBoxContainer = $RelicContainer

@onready var time_label: Label = $"../../TopCenter/TimeLabel"
@onready var kill_label: Label = $"../../TopCenter/KillLabel"
@onready var score_label: Label = $"../../TopCenter/ScoreLabel"

func _ready() -> void:
	SignalBus.player_hp_changed.connect(update_hp)
	SignalBus.player_exp_changed.connect(update_exp)
	SignalBus.relic_acquired.connect(add_relic_icon)

func update_hp(current_hp: int, max_hp: int) -> void:
	if not hp_bar or not hp_label: return
	hp_bar.max_value = max_hp
	hp_bar.value = current_hp
	hp_label.text = "HP: %d / %d" % [current_hp, max_hp]

func update_exp(current_exp: int, max_exp: int, level: int) -> void:
	if not exp_bar or not level_label: return
	exp_bar.max_value = max_exp
	exp_bar.value = current_exp
	level_label.text = "Lv. %d" % level

func update_time(time_seconds: float) -> void:
	if not time_label: return
	var mins: int = int(time_seconds / 60.0)
	var secs: int = int(time_seconds) % 60
	time_label.text = "%02d:%02d" % [mins, secs]

func update_kills(kills: int) -> void:
	if kill_label:
		kill_label.text = "Kills: %d" % kills

func update_score(score: int) -> void:
	if score_label:
