					"meteor": w_title = "☄️ メテオ"; w_desc = "ダメージと落下数アップ"
					"laser": w_title = "⚡ レーザー"; w_desc = "ダメージと太さアップ"
				available.append({"id": "upgrade_" + weapon_id, "title": w_title + "強化", "desc": w_desc + " (Lv" + str(lvl + 1) + ")"})

	available.shuffle()
	var choices = available.slice(0, min(3, available.size()))
	_create_cards(choices, _on_upgrade_button_pressed)

	visible = true
	get_tree().paused = true

func show_boss_reward_options() -> void:
	for child in cards_container.get_children():
		child.queue_free()

	title_label.text = "👑 ボス討伐報酬！ 武器強化 👑"

	var choices = []
	var players = get_tree().get_nodes_in_group("player")
	if players.size() > 0:
		var p = players[0]

		if p.weapon_levels.has("orbit"):
			if p.weapon_levels["orbit"] >= 3:
				choices.append({"id": "evolve_orbit", "title": "🩸 血のオービット (進化)", "desc": "巨大化し、ダメージを与えた際に確率でHPを回復する"})
			else:
				choices.append({"id": "upgrade_orbit", "title": "🌀 オービット強化", "desc": "オービットの威力と回転速度が上がる (Lv" + str(p.weapon_levels["orbit"]+1) + ")"})

		if p.weapon_levels.has("melee"):
			if p.weapon_levels["melee"] >= 3:
				choices.append({"id": "evolve_melee", "title": "🗡️ 大剣の斬撃 (進化)", "desc": "画面半分を覆う巨大な斬撃を放つ"})
			else:
				choices.append({"id": "upgrade_melee", "title": "⚔️ ムチ強化", "desc": "ムチの威力と攻撃頻度が上がる (Lv" + str(p.weapon_levels["melee"]+1) + ")"})

		if p.weapon_levels.has("meteor"):
			if p.weapon_levels["meteor"] >= 3:
				choices.append({"id": "evolve_meteor", "title": "🌌 ブラックホール (進化)", "desc": "着弾後に周囲の敵を吸い寄せ、継続ダメージを与える"})
			else:
				choices.append({"id": "upgrade_meteor", "title": "☄️ メテオ強化", "desc": "メテオの威力と落下数が増える (Lv" + str(p.weapon_levels["meteor"]+1) + ")"})

		if p.weapon_levels.has("laser"):
			if p.weapon_levels["laser"] >= 3:
				choices.append({"id": "evolve_laser", "title": "💥 デスレーザー (進化)", "desc": "極太のレーザーを放ち、敵を吹き飛ばす"})
