	_create_cards(choices, _on_weapon_button_pressed)

	visible = true
	get_tree().paused = true

func _create_cards(choices: Array, callback: Callable) -> void:
	for choice in choices:
		var card = Button.new()
		card.custom_minimum_size = Vector2(240, 200)
		card.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		card.size_flags_vertical = Control.SIZE_EXPAND_FILL
		card.alignment = HORIZONTAL_ALIGNMENT_CENTER

		var vbox = VBoxContainer.new()
		vbox.set_anchors_preset(Control.PRESET_FULL_RECT)
		vbox.alignment = BoxContainer.ALIGNMENT_CENTER
		vbox.mouse_filter = Control.MOUSE_FILTER_IGNORE

		var title = Label.new()
		title.text = choice.title
		title.add_theme_font_size_override("font_size", 18)
		title.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
		title.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
		vbox.add_child(title)

		var spacer = Control.new()
		spacer.custom_minimum_size = Vector2(0, 10)
		vbox.add_child(spacer)

		var desc = Label.new()
		desc.text = choice.desc
		desc.add_theme_font_size_override("font_size", 13)
		desc.add_theme_color_override("font_color", Color(0.85, 0.85, 0.85, 1))
		desc.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
		desc.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
		vbox.add_child(desc)

		card.add_child(vbox)

		var upgrade_id: String = choice.id
		card.pressed.connect(func(): callback.call(upgrade_id))
		cards_container.add_child(card)

func _on_upgrade_button_pressed(upgrade_id: String) -> void:
	visible = false
	get_tree().paused = false
	var players = get_tree().get_nodes_in_group("player")
