		players[0].apply_upgrade(upgrade_id)

func _on_weapon_button_pressed(weapon_id: String) -> void:
	visible = false
	get_tree().paused = false
	var players = get_tree().get_nodes_in_group("player")
	if players.size() > 0:
		players[0].apply_upgrade(weapon_id)
')

