command($code = @"
extends Node2D
class_name ActiveSkillManager

signal skill_cooldown_started(max_cd: float)
signal skill_cooldown_updated(current_cd: float, max_cd: float)
signal skill_ready()

var current_cooldown: float = 0.0
var max_cooldown: float = 10.0
var skill_id: String = ""

@onready var player = get_parent()
var skill_duration_timer: Timer

func _ready() -> void:
	skill_id = Global.selected_skill
	_setup_skill()

	skill_duration_timer = Timer.new()
	skill_duration_timer.one_shot = true
	add_child(skill_duration_timer)

func _setup_skill() -> void:
	match skill_id:
		"bash": max_cooldown = 8.0
		"warcry": max_cooldown = 20.0
		"quake": max_cooldown = 15.0
		"dash": max_cooldown = 6.0
		"poison": max_cooldown = 12.0
		"time": max_cooldown = 25.0
		"blackhole": max_cooldown = 15.0
		"shield": max_cooldown = 20.0
		"meteor": max_cooldown = 12.0
		_: max_cooldown = 10.0

func _process(delta: float) -> void:
	if current_cooldown > 0:
		current_cooldown -= delta
		skill_cooldown_updated.emit(max(0.0, current_cooldown), max_cooldown)
		if current_cooldown <= 0:
			skill_ready.emit()

func _input(event: InputEvent) -> void:
	if event.is_action_pressed("use_skill") and current_cooldown <= 0:
		_use_skill()

func _use_skill() -> void:
	current_cooldown = max_cooldown
	skill_cooldown_started.emit(max_cooldown)

	match skill_id:
		"bash": _skill_bash()
		"warcry": _skill_warcry()
		"quake": _skill_quake()
		"dash": _skill_dash()
		"poison": _skill_poison()
		"time": _skill_time()
		"blackhole": _skill_blackhole()
		"shield": _skill_shield()
		"meteor": _skill_meteor()

func _skill_bash() -> void:
	var dir = player.input_comp.get_movement_vector()
	if dir == Vector2.ZERO: dir = Vector2.RIGHT
	player.global_position += dir * 150.0
	var enemies = get_tree().get_nodes_in_group("enemy")
	for e in enemies:
		if e.global_position.distance_to(player.global_position) < 180:
			e.take_damage(50, dir)
			e.global_position += dir * 100

func _skill_warcry() -> void:
	player.health_comp.is_invincible = true
	var enemies = get_tree().get_nodes_in_group("enemy")
	for e in enemies: e.speed *= 0.5
	skill_duration_timer.start(5.0)
	skill_duration_timer.timeout.connect(func():
		if is_instance_valid(player): player.health_comp.is_invincible = false
		var cur = get_tree().get_nodes_in_group("enemy")
		for ce in cur: ce.speed *= 2.0
	, CONNECT_ONE_SHOT)

func _skill_quake() -> void:
	var enemies = get_tree().get_nodes_in_group("enemy")
	for e in enemies:
		e.take_damage(40, Vector2.ZERO)
		e.speed = 0.0
	skill_duration_timer.start(2.0)
	skill_duration_timer.timeout.connect(func():
		var cur = get_tree().get_nodes_in_group("enemy")
		for ce in cur: ce.speed = 125.0
	, CONNECT_ONE_SHOT)

func _skill_dash() -> void:
	var dir = player.input_comp.get_movement_vector()
	if dir == Vector2.ZERO: dir = Vector2.RIGHT
	var start_pos = player.global_position
	player.global_position += dir * 250.0
	var enemies = get_tree().get_nodes_in_group("enemy")
	for e in enemies:
		if e.global_position.distance_to(start_pos) < 250 or e.global_position.distance_to(player.global_position) < 250:
			e.take_damage(60, dir)

func _skill_poison() -> void:
	var enemies = get_tree().get_nodes_in_group("enemy")
	for e in enemies:
		if e.global_position.distance_to(player.global_position) < 250:
			e.take_damage(100, Vector2.ZERO)
			e.speed *= 0.5

func _skill_time() -> void:
	Engine.time_scale = 0.3
	skill_duration_timer.start(1.0)
	skill_duration_timer.timeout.connect(func(): Engine.time_scale = 1.0, CONNECT_ONE_SHOT)

func _skill_blackhole() -> void:
	var center = player.global_position
	var enemies = get_tree().get_nodes_in_group("enemy")
	for e in enemies:
		if e.global_position.distance_to(center) < 400:
			e.global_position = e.global_position.move_toward(center, 150)
			e.take_damage(80, Vector2.ZERO)

func _skill_shield() -> void:
	player.health_comp.is_invincible = true
	skill_duration_timer.start(4.0)
	skill_duration_timer.timeout.connect(func():
		if is_instance_valid(player): player.health_comp.is_invincible = false
		var enemies = get_tree().get_nodes_in_group("enemy")
		for e in enemies:
			if e.global_position.distance_to(player.global_position) < 300:
				e.take_damage(120, Vector2.ZERO)
	, CONNECT_ONE_SHOT)

func _skill_meteor() -> void:
	var enemies = get_tree().get_nodes_in_group("enemy")
	enemies.shuffle()
	var limit = min(8, enemies.size())
	for i in range(limit):
		var e = enemies[i]
		e.take_damage(200, Vector2.ZERO)
		var exp_scene = load("res://scenes/explosion_effect.tscn")
		if exp_scene:
			var exp = exp_scene.instantiate()
			exp.global_position = e.global_position
			exp.scale = Vector2(2, 2)
			get_tree().current_scene.add_child(exp)
"@
Set-Content -Path 'c:\Users\remak\source\repos\AsaSurvivor\scripts\components\active_skill_manager.gd' -Value $code -Encoding UTF8
)

