	[Header("色・点滅 (フリッカー)")]
	[SerializeField, Tooltip("色チラつきを有効にするか")]
	private bool enableColorFlicker = true;

	[SerializeField, Tooltip("グリッチ発生時の色")]
	private Color glitchColor = new Color(0.2f, 0.9f, 1f, 1f);

