command(@'
using System.Collections;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class ScreenGlitchEffect : MonoBehaviour
{
	[Header("カメラシェイク（画面の揺れ）")]
	[SerializeField, Tooltip("画面揺れを有効にするか")]
	private bool enableCameraShake = true;

	[SerializeField, Tooltip("対象カメラ（空の場合はMainCameraを自動取得）")]
	private Camera targetCamera;

	[SerializeField, Tooltip("揺れの強さ")]
	private float shakeIntensity = 0.08f;

	[Header("URP ボリューム制御 (Weight連動)")]
	[SerializeField, Tooltip("グリッチ時のみWeightを上げる専用Volume（指定がある場合）")]
	private Volume glitchVolume;

	[Header("URP ポストプロセス直接制御 (色収差・歪み)")]
	[SerializeField, Tooltip("ポストプロセス制御対象のVolume（空ならScene上のGlobalVolumeを自動探索）")]
	private Volume postProcessVolume;

	[SerializeField, Tooltip("色収差（RGBズレ）を有効にするか")]
	private bool enableChromaticAberration = true;

	[SerializeField, Range(0f, 1f), Tooltip("ノイズ発生時の色収差の強さ")]
	private float glitchChromaticAberration = 1.0f;

	[SerializeField, Tooltip("画面歪みを有効にするか")]
	private bool enableLensDistortion = true;

	[SerializeField, Range(-1f, 1f), Tooltip("ノイズ発生時の歪み量")]
	private float glitchLensDistortion = -0.2f;

	[Header("画面オーバーレイ / フラッシュ (UI)")]
	[SerializeField, Tooltip("画面フラッシュ用のCanvasGroup（黒・白・走査線画像など）")]
	private CanvasGroup overlayCanvasGroup;

	[SerializeField, Range(0f, 1f), Tooltip("ノイズ発生時のオーバーレイ透明度")]
	private float overlayAlpha = 0.25f;

	private Vector3 cameraInitialPos;
	private ChromaticAberration chromaticAberration;
	private LensDistortion lensDistortion;

	private float defaultChromatic;
	private float defaultDistortion;
	private Coroutine currentCoroutine;

	private void Awake()
	{
		if (targetCamera == null)
		{
			targetCamera = Camera.main;
		}

		if (postProcessVolume == null && glitchVolume == null)
		{
			postProcessVolume = FindFirstObjectByType<Volume>();
		}

		InitializePostProcessing();
	}

	private void InitializePostProcessing()
	{
		if (postProcessVolume != null && postProcessVolume.profile != null)
		{
			// 色収差
			if (!postProcessVolume.profile.TryGet(out chromaticAberration))
			{
				chromaticAberration = postProcessVolume.profile.Add<ChromaticAberration>(true);
				chromaticAberration.active = true;
				chromaticAberration.intensity.overrideState = true;
				chromaticAberration.intensity.value = 0f;
			}
			defaultChromatic = chromaticAberration.intensity.value;

			// 画面歪み
			if (!postProcessVolume.profile.TryGet(out lensDistortion))
			{
				lensDistortion = postProcessVolume.profile.Add<LensDistortion>(true);
				lensDistortion.active = true;
				lensDistortion.intensity.overrideState = true;
				lensDistortion.intensity.value = 0f;
			}
			defaultDistortion = lensDistortion.intensity.value;
		}

		if (glitchVolume != null)
		{
			glitchVolume.weight = 0f;
		}

		if (overlayCanvasGroup != null)
		{
			overlayCanvasGroup.alpha = 0f;
		}
	}

	/// <summary>
	/// 外部（TextGlitchEffectなど）から呼び出して画面全体ノイズを実行
	/// </summary>
	public void TriggerGlitch(float duration)
	{
		if (currentCoroutine != null)
		{
			StopCoroutine(currentCoroutine);
			ResetState();
		}

		currentCoroutine = StartCoroutine(GlitchRoutine(duration));
	}

	private IEnumerator GlitchRoutine(float duration)
	{
		if (targetCamera != null)
		{
			cameraInitialPos = targetCamera.transform.localPosition;
		}

		float elapsed = 0f;

		// 専用Volumeがある場合はWeightを1に
		if (glitchVolume != null)
		{
			glitchVolume.weight = 1f;
		}

		while (elapsed < duration)
		{
			// 1. カメラシェイク
			if (enableCameraShake && targetCamera != null)
			{
				Vector2 randomOffset = Random.insideUnitCircle * shakeIntensity;
				targetCamera.transform.localPosition = cameraInitialPos + new Vector3(randomOffset.x, randomOffset.y, 0f);
			}

			// 2. ポストプロセス（色収差・歪み）
			if (chromaticAberration != null && enableChromaticAberration)
			{
				chromaticAberration.intensity.value = (Random.value > 0.3f) ? glitchChromaticAberration : 0f;
			}

			if (lensDistortion != null && enableLensDistortion)
			{
				lensDistortion.intensity.value = (Random.value > 0.3f) ? glitchLensDistortion : 0f;
			}

			// 3. UIオーバーレイの点滅
			if (overlayCanvasGroup != null)
			{
				overlayCanvasGroup.alpha = (Random.value > 0.4f) ? overlayAlpha : 0f;
			}

			float step = Random.Range(0.02f, 0.05f);
			yield return new WaitForSeconds(step);
			elapsed += step;
		}

		ResetState();
		currentCoroutine = null;
	}

	private void ResetState()
	{
		if (targetCamera != null)
		{
			targetCamera.transform.localPosition = cameraInitialPos;
		}

		if (chromaticAberration != null)
		{
			chromaticAberration.intensity.value = defaultChromatic;
		}

		if (lensDistortion != null)
		{
			lensDistortion.intensity.value = defaultDistortion;
		}

		if (glitchVolume != null)
		{
			glitchVolume.weight = 0f;
		}

		if (overlayCanvasGroup != null)
		{
			overlayCanvasGroup.alpha = 0f;
		}
	}

	private void OnDisable()
	{
		if (currentCoroutine != null)
		{
			StopCoroutine(currentCoroutine);
			currentCoroutine = null;
		}
		ResetState();
	}
}
