command(@'
Shader "UI/GlitchScanline"
{
	Properties
	{
		[PerRendererData] _MainTex ("Sprite Texture", 2D) = "white" {}
		_Color ("Tint", Color) = (1,1,1,1)
		_GlitchColor ("Glitch Line Color", Color) = (0.2, 0.9, 1.0, 0.8)
		_DarkLineColor ("Dark Line Color", Color) = (0.0, 0.0, 0.0, 0.7)
		_Intensity ("Intensity", Range(0, 1)) = 0.0
		_ScanlineCount ("Scanline Count", Float) = 350.0
		_ScanlineIntensity ("Scanline Intensity", Range(0, 1)) = 0.4
		_GlitchBarFrequency ("Bar Frequency", Float) = 25.0
		_GlitchBarIntensity ("Bar Intensity", Range(0, 1)) = 0.85
		_JitterSpeed ("Jitter Speed", Float) = 35.0

		_StencilComp ("Stencil Comparison", Float) = 8
		_Stencil ("Stencil ID", Float) = 0
		_StencilOp ("Stencil Operation", Float) = 0
		_StencilWriteMask ("Stencil Write Mask", Float) = 255
		_StencilReadMask ("Stencil Read Mask", Float) = 255
		_ColorMask ("Color Mask", Float) = 15
		[Toggle(UNITY_UI_ALPHACLIP)] _UseUIAlphaClip ("Use Alpha Clip", Float) = 0
	}

	SubShader
	{
		Tags
		{
			"Queue"="Transparent"
			"IgnoreProjector"="True"
			"RenderType"="Transparent"
			"PreviewType"="Plane"
			"CanUseSpriteAtlas"="True"
		}

		Stencil
		{
			Ref [_Stencil]
			Comp [_StencilComp]
			Pass [_StencilOp]
			ReadMask [_StencilReadMask]
			WriteMask [_StencilWriteMask]
		}

		Cull Off
		Lighting Off
		ZWrite Off
		ZTest [unity_GUIZTestMode]
		Blend SrcAlpha OneMinusSrcAlpha
		ColorMask [_ColorMask]

		Pass
		{
			Name "Default"
		CGPROGRAM
			#pragma vertex vert
			#pragma fragment frag
			#pragma target 2.0

			#include "UnityCG.cginc"
			#include "UnityUI.cginc"

			#pragma multi_compile_local _ UNITY_UI_CLIP_RECT
			#pragma multi_compile_local _ UNITY_UI_ALPHACLIP

			struct appdata_t
			{
				float4 vertex   : POSITION;
				float4 color    : COLOR;
				float2 texcoord : TEXCOORD0;
				UNITY_VERTEX_INPUT_INSTANCE_ID
			};

			struct v2f
			{
				float4 vertex   : SV_POSITION;
				fixed4 color    : COLOR;
				float2 texcoord  : TEXCOORD0;
				float4 worldPosition : TEXCOORD1;
				UNITY_VERTEX_OUTPUT_STEREO
			};

			sampler2D _MainTex;
			fixed4 _Color;
			fixed4 _GlitchColor;
			fixed4 _DarkLineColor;
			float _Intensity;
			float _ScanlineCount;
			float _ScanlineIntensity;
			float _GlitchBarFrequency;
			float _GlitchBarIntensity;
			float _JitterSpeed;
			float4 _ClipRect;
			float4 _MainTex_ST;

			float hash(float n)
			{
				return frac(sin(n) * 43758.5453123);
			}

			v2f vert(appdata_t v)
			{
				v2f OUT;
				UNITY_SETUP_INSTANCE_ID(v);
				UNITY_INITIALIZE_VERTEX_OUTPUT_STEREO(OUT);
				OUT.worldPosition = v.vertex;
				OUT.vertex = UnityObjectToClipPos(OUT.worldPosition);
				OUT.texcoord = TRANSFORM_TEX(v.texcoord, _MainTex);
				OUT.color = v.color * _Color;
				return OUT;
			}

			fixed4 frag(v2f IN) : SV_Target
			{
				if (_Intensity <= 0.001)
				{
					return fixed4(0, 0, 0, 0);
				}

				float2 uv = IN.texcoord;
				float timeBlock = floor(_Time.y * _JitterSpeed);

				// 1. 水平走査線 (細い横線)
				float scanline = sin(uv.y * _ScanlineCount) * 0.5 + 0.5;
				scanline = pow(scanline, 2.0) * _ScanlineIntensity;

				// 2. ランダムな横帯・横線グリッチ
				float barIndex = floor(uv.y * _GlitchBarFrequency);
				float barRandom = hash(barIndex + timeBlock * 17.13);
				float barActive = step(0.65, barRandom); // 確率でその行に帯が発生
				float barBrightness = hash(barIndex + timeBlock * 53.71);

				// 横帯の色決定
				fixed4 lineCol = lerp(_DarkLineColor, _GlitchColor, barBrightness);
				float lineAlpha = barActive * _GlitchBarIntensity;

				// 合成
				fixed4 finalColor = lineCol;
				finalColor.a = saturate(lineAlpha + scanline) * _Intensity * IN.color.a;

				#ifdef UNITY_UI_CLIP_RECT
				finalColor.a *= UnityGet2DClipping(IN.worldPosition.xy, _ClipRect);
				#endif

				#ifdef UNITY_UI_ALPHACLIP
				clip(finalColor.a - 0.001);
				#endif

				return finalColor;
			}
		ENDCG
		}
	}
}
